257	    @Override
258	    @Transactional
259	    public void createOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
260	        rejectWhenDailyLimitReached(owner);
261	        rejectWhenCityAtCapacity(owner);
262	        owner.setHouseholdId(deriveHouseholdId(owner));
263	        List<Owner> householdMembers = findHouseholdMembers(owner);
264	        rejectWhenHouseholdDuplicate(owner, householdMembers, sharesHousehold);
265	        assignPossibleDuplicate(owner);
266	        owner.setHouseholdMemberCount(householdMembers.size() + 1);
267	        if (owner.getCustomerCode() == null) {
268	            owner.setCustomerCode(deduplicateCustomerCode(deriveCustomerCode(owner)));
269	        }
270	        if (owner.getNamesakeCount() == null) {
271	            owner.setNamesakeCount(countNamesakes(owner));
272	        }
273	        owner.setBulkSignupWarning(exceedsBulkSignupThreshold(owner));
274	        ownerRepository.save(owner);
275	    }
276	
277	    /** Number of owners created on a single day beyond which the bulk-signup warning is raised. */
278	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
279	
280	    /**
281	     * Whether more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created
282	     * today (compared by {@code registrationDate}), evaluated before this owner is persisted so it
283	     * reflects the owners present at creation time. The new owner's registration date, defaulted to
284	     * today by the controller, determines which day is counted — the same accumulation path as the
285	     * daily-limit rule.
286	     */
287	    private boolean exceedsBulkSignupThreshold(Owner owner) {
288	        LocalDate day = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
289	        return countOwnersRegisteredOn(day) > BULK_SIGNUP_WARNING_THRESHOLD;
290	    }
291	
292	    /**
293	     * Count the existing owners that already share this owner's first name and last name,
294	     * compared case-insensitively (with surrounding/collapsed whitespace ignored). Evaluated
295	     * before the owner is persisted, so it reflects the owners present at creation time.
296	     */
297	    private int countNamesakes(Owner owner) {
298	        String firstName = IdentityNormalizer.normalize(owner.getFirstName());
299	        String lastName = IdentityNormalizer.normalize(owner.getLastName());
300	        return (int) ownerRepository.findAll().stream()
301	            .filter(existing -> firstName.equals(IdentityNormalizer.normalize(existing.getFirstName()))
302	                && lastName.equals(IdentityNormalizer.normalize(existing.getLastName())))
303	            .count();
304	    }
305	
306	    /**
307	     * The existing owners that already belong to this owner's household, i.e. those carrying the
308	     * same deterministic {@code householdId} (see {@link #deriveHouseholdId(Owner)}). Because the
309	     * household id is derived purely from the normalized last name and postcode, this is exactly
310	     * the set of owners sharing that last name and postcode. Evaluated before the owner is
311	     * persisted, so it reflects the owners present at creation time. The owner's own
312	     * {@code householdId} must already be assigned before calling.
313	     */
314	    private List<Owner> findHouseholdMembers(Owner owner) {
315	        String householdId = owner.getHouseholdId();
316	        return ownerRepository.findAll().stream()
317	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
318	            .toList();
319	    }
320	
321	    /**
322	     * Derive the owner's deterministic household identifier: the first twelve hexadecimal characters
323	     * of the SHA-256 digest over {@code normalizedLastName + '|' + postcode}. Two owners with the
324	     * same last name (compared case-insensitively with collapsed whitespace) and postcode therefore
325	     * map to the same value automatically, without any opt-in, so they form one household.
326	     */
327	    private static String deriveHouseholdId(Owner owner) {
328	        String lastName = IdentityNormalizer.normalize(owner.getLastName());
329	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
330	        return sha256HexPrefix(lastName + "|" + postcode, 12);
331	    }
332	
333	    /**
334	     * Reject the create when another owner already belongs to this owner's household (same
335	     * deterministic {@code householdId}, i.e. the same last name and postcode) as a
336	     * {@code 409 Conflict}. The single exception to the block is {@code sharesHousehold}: when set
337	     * the new owner is accepted as a declared member of the existing household rather than rejected.
338	     * Evaluated after the household id has been assigned and before the owner is persisted, so it
339	     * reflects the owners present at creation time.
340	     */
341	    private void rejectWhenHouseholdDuplicate(Owner owner, List<Owner> householdMembers, boolean sharesHousehold) {
342	        if (!householdMembers.isEmpty() && !sharesHousehold) {
343	            throw new DuplicateIdentityException(
344	                "an owner already exists in household " + owner.getHouseholdId());
345	        }
346	    }
347	
348	    /**
349	     * Set the new owner's soft-duplicate flags. A declared member of an existing household (reached
350	     * only via {@code sharesHousehold}) is explicitly not a suspected duplicate, and an owner that
351	     * is the first in its household has nothing to be a duplicate of; any other case would already
352	     * have been rejected as a household duplicate. The flags are therefore always cleared here, but
353	     * set explicitly so the field is always present in the response. Evaluated after the
354	     * household-duplicate check and before the owner is persisted.
355	     */
356	    private void assignPossibleDuplicate(Owner owner) {
357	        owner.setPossibleDuplicate(false);
358	        owner.setPossibleDuplicateOf(null);
359	    }
360	
361	    /** Maximum number of owners that may be created on any single day (by registration date). */
362	    private static final long DAILY_OWNER_LIMIT = 100L;
363	
364	    /**
365	     * Reject the create when {@value #DAILY_OWNER_LIMIT} or more owners have already been created
366	     * today (compared by {@code registrationDate}). Evaluated before the owner is persisted, so it
367	     * reflects the owners present at creation time. The new owner's own registration date, defaulted
368	     * to today by the controller, determines which day the limit is checked against.
369	     */
370	    private void rejectWhenDailyLimitReached(Owner owner) {
371	        LocalDate day = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
372	        if (countOwnersRegisteredOn(day) >= DAILY_OWNER_LIMIT) {
373	            throw new DailyOwnerLimitExceededException(
374	                DAILY_OWNER_LIMIT + " or more owners have already been created on " + day);
375	        }
376	    }
377	
378	    /**
379	     * Count the existing owners whose {@code registrationDate} equals the given day. Evaluated
380	     * before the owner is persisted, so it reflects the owners present at creation time.
381	     */
382	    private long countOwnersRegisteredOn(LocalDate day) {
383	        return ownerRepository.findAll().stream()
384	            .filter(existing -> day.equals(existing.getRegistrationDate()))
385	            .count();
386	    }
387	
388	    /** Maximum number of owners allowed to live in any single city. */
389	    private static final long CITY_CAPACITY = 50L;
390	
391	    /**
392	     * Reject the create when the owner's city already contains {@value #CITY_CAPACITY} or more
393	     * owners (compared case-insensitively with collapsed whitespace). Evaluated before the owner
394	     * is persisted, so it reflects the owners present at creation time.
395	     */
396	    private void rejectWhenCityAtCapacity(Owner owner) {
397	        if (countOwnersInCity(owner) >= CITY_CAPACITY) {
398	            throw new CityCapacityExceededException(
399	                "city " + owner.getCity() + " already contains " + CITY_CAPACITY + " or more owners");
400	        }
401	    }
402	
403	    /**
404	     * Count the existing owners that already live in this owner's city, compared
405	     * case-insensitively (with surrounding/collapsed whitespace ignored). Evaluated before the
406	     * owner is persisted, so it reflects the owners present at creation time.
407	     */
408	    private long countOwnersInCity(Owner owner) {
409	        String city = IdentityNormalizer.normalize(owner.getCity());
410	        return ownerRepository.findAll().stream()
411	            .filter(existing -> city.equals(IdentityNormalizer.normalize(existing.getCity())))
412	            .count();
413	    }
414	
415	    /** Region-to-inclusive 4-digit postcode range {@code {low, high}}. */
416	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
417	        "NSW", new int[] {2000, 2099},
418	        "VIC", new int[] {3000, 3099},
419	        "QLD", new int[] {4000, 4099});
420	
421	    /** Region code used when the postcode maps to no known region (or is absent). */
422	    private static final String UNKNOWN_REGION = "UNKNOWN";
423	
424	    /**
425	     * Builds the customer code {@code '<REGION>-<HASH8>'}: the region code derived from the
426	     * owner's postcode, a hyphen, and the first eight upper-case hexadecimal characters of the
427	     * SHA-256 digest over the owner's normalized (E.164) telephone concatenated with the last
428	     * name. No sequence number is used; the identity is fully derived from the region and hash.
429	     */
430	    private String deriveCustomerCode(Owner owner) {
431	        String region = regionForPostcode(owner.getPostcode());
432	        String telephone = TelephoneNormalizer.toComparable(owner.getTelephone());
433	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
434	        return region + "-" + sha256Hex8(telephone + lastName);
435	    }
436	
437	    /**
438	     * De-duplicates a computed {@code customerCode} against the existing owners: if no owner already
439	     * carries {@code baseCode} it is returned unchanged, otherwise {@code '-<n>'} is appended with the
440	     * smallest {@code n} of 2 or more that yields a value no existing owner holds. Evaluated before the
441	     * owner is persisted, so it reflects the owners present at creation time.
442	     */
443	    private String deduplicateCustomerCode(String baseCode) {
444	        Set<String> existingCodes = ownerRepository.findAll().stream()
445	            .map(Owner::getCustomerCode)
446	            .filter(Objects::nonNull)
447	            .collect(Collectors.toSet());
448	        if (!existingCodes.contains(baseCode)) {
449	            return baseCode;
450	        }
451	        int n = 2;
452	        while (existingCodes.contains(baseCode + "-" + n)) {
453	            n++;
454	        }
455	        return baseCode + "-" + n;
456	    }
457	
458	    /**
459	     * Returns the region code whose inclusive postcode range contains {@code postcode}
460	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), or
461	     * {@code "UNKNOWN"} when the postcode is absent, not a 4-digit value, or in no known range.
462	     */
463	    private static String regionForPostcode(String postcode) {
464	        if (postcode == null || !postcode.matches("\\d{4}")) {
465	            return UNKNOWN_REGION;
466	        }
467	        int value = Integer.parseInt(postcode);
468	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
469	            int[] range = entry.getValue();
470	            if (value >= range[0] && value <= range[1]) {
471	                return entry.getKey();
472	            }
473	        }
474	        return UNKNOWN_REGION;
475	    }
476	
477	    /**
478	     * Returns the first eight upper-case hexadecimal characters (the first four bytes) of the
479	     * SHA-256 digest of the UTF-8 bytes of {@code value}.
480	     */
481	    private static String sha256Hex8(String value) {
482	        return sha256HexPrefix(value, 8).toUpperCase();
483	    }
484	
485	    /**
486	     * Returns the first {@code hexChars} lower-case hexadecimal characters of the SHA-256 digest of
487	     * the UTF-8 bytes of {@code value}.
488	     */
489	    private static String sha256HexPrefix(String value, int hexChars) {
490	        try {
491	            byte[] digest = MessageDigest.getInstance("SHA-256")
492	                .digest(value.getBytes(StandardCharsets.UTF_8));
493	            StringBuilder sb = new StringBuilder(hexChars);
494	            for (int i = 0; sb.length() < hexChars; i++) {
495	                sb.append(String.format("%02x", digest[i]));
496	            }
497	            return sb.substring(0, hexChars);
498	        }
499	        catch (NoSuchAlgorithmException e) {
500	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
501	        }
502	    }
